def build_floor_from_strings(lines):
    return [list(row) for row in lines]


def build_campus_map():
    floors = [LOWER_GROUND, GROUND, FIRST, SECOND, THIRD, FOURTH]
    return [build_floor_from_strings(f) for f in floors]
